contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint lockTime) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (0));
        (uint beforeUnlock, uint beforeAccBalance) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractBalance = address(c).balance;

        c.Put{value: 0}(lockTime); if (__ESBMC_reverted()) return;

        (uint afterUnlock, uint afterAccBalance) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint afterContractBalance = address(c).balance;

        assert(afterAccBalance == beforeAccBalance && afterContractBalance == beforeContractBalance);
    }

    receive() external payable {}
}

